package io.tenvyr.executorhost;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.Json;
import io.tenvyr.worker.Cancellation;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;

/** Config, native output and real process-group regression suite. No sockets or model credentials. */
public final class ExecutorHostCheck {
    private static Path launcher,root;
    static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    static void rejects(Runnable run){try{run.run();throw new AssertionError("Expected rejection");}catch(IllegalArgumentException expected){}}
    static HostConfig.Profile profile(String mode,long wall,int out,int err,String kind,String...extra){List<String> args=new ArrayList<>(List.of("-cp",System.getProperty("java.class.path"),FakeProcess.class.getName(),mode));args.addAll(List.of(extra));return new HostConfig.Profile("fixture",Path.of(System.getProperty("java.home"),"bin","java").toString(),args,root,Map.of(),Map.of(),wall,out,err,4100,"TOKEN",null,null,kind,true,null,false);}
    static Supervisor.Outcome run(HostConfig.Profile p)throws Exception{return Supervisor.supervise(launcher,p,Map.of(),Json.object("opaque","input"),null,new Cancellation(),null,root,null,100);}
    static NativeOutput.Result nativeResult(String kind,String text){return NativeOutput.adapt(new Supervisor.Outcome("succeeded",0,text,"",null,null,null,null),profile("echo",2000,65536,65536,kind));}
    public static void main(String[] args)throws Exception {
        Path repo=Path.of(args.length>0?args[0]:".").toAbsolutePath();launcher=repo.resolve("backend/executor-host/native/tenvyr-process-launcher");root=Files.createTempDirectory("tenvyr-executor-check-").toRealPath();System.setProperty("java.class.path",String.join(java.io.File.pathSeparator,Arrays.stream(System.getProperty("java.class.path").split(java.io.File.pathSeparator)).map(p->Path.of(p).toAbsolutePath().normalize().toString()).toList()));
        try{
            nativeChecks();configChecks(repo);
            Supervisor.Outcome echoed=run(profile("echo",2000,65536,65536,"generic-cli"));check(echoed.kind().equals("succeeded")&&Json.parse(echoed.stdout()).path("opaque").asText().equals("input")&&echoed.stderr().equals("stderr-ok"),"Opaque stdin and bounded capture");
            Supervisor.Outcome failed=run(profile("fail",2000,65536,65536,"generic-cli"));check(failed.kind().equals("failed")&&failed.exitCode()==3,"Nonzero native exit");
            HostConfig.Profile argv=profile("argv",2000,65536,65536,"generic-cli","literal;$(touch sentinel)");check(run(argv).stdout().trim().equals("literal;$(touch sentinel)")&&!Files.exists(root.resolve("sentinel")),"No shell interpretation");
            Supervisor.Outcome environment=Supervisor.supervise(launcher,profile("env",2000,65536,65536,"generic-cli"),Map.of("ALLOWED","yes","SECRET","private"),Json.object(),null,new Cancellation(),null,root,null,100);check(environment.stdout().equals("yes|private|absent"),"Explicit environment only");
            check(run(profile("cwd",2000,65536,65536,"generic-cli")).stdout().equals(root.toString()),"Authoritative cwd");
            for(String stream:List.of("stdout","stderr")){Supervisor.Outcome limit=run(profile(stream,2000,1024,1024,"generic-cli"));check(limit.kind().equals("output_limit")&&limit.stream().equals(stream),"Byte bound "+stream);}
            Supervisor.Outcome deadline=Supervisor.supervise(launcher,profile("sleep",2000,65536,65536,"generic-cli"),Map.of(),Json.object(),null,new Cancellation(),Instant.now().minusSeconds(1).toString(),root,null,100);check(deadline.kind().equals("killed")&&deadline.trigger().equals("invocation_deadline"),"Past invocation deadline");
            Cancellation cancellation=new Cancellation();ExecutorService pool=Executors.newSingleThreadExecutor();try{Future<Supervisor.Outcome> running=pool.submit(()->Supervisor.supervise(launcher,profile("sleep",2000,65536,65536,"generic-cli"),Map.of(),Json.object(),null,cancellation,null,root,null,100));Thread.sleep(100);cancellation.cancel();check(running.get(3,TimeUnit.SECONDS).trigger().equals("shutdown"),"Shutdown kills session");}finally{pool.shutdownNow();}
            realTreeKill("tree",true);realTreeKill("tree-exit",false);orphanChecks();
            System.out.println("Executor host config/native/process-group checks passed");
        }finally{try(var paths=Files.walk(root)){for(Path p:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}
    }
    static void nativeChecks(){
        for(String kind:List.of("generic-cli","claude","codex","opencode")){NativeOutput.Result direct=nativeResult(kind,"{\"tasks\":[]}");check(direct.success()&&direct.output().path("tasks").isArray(),"Direct JSON "+kind);check(!nativeResult(kind,"not JSON").success(),"Malformed native output "+kind);check(!nativeResult(kind,"").success(),"Empty native output "+kind);}
        String codex="{\"type\":\"thread.started\"}\n{\"type\":\"item.completed\",\"item\":{\"type\":\"agent_message\",\"text\":\"{\\\"first\\\":true}\"}}\n{\"type\":\"item.completed\",\"item\":{\"type\":\"agent_message\",\"text\":\"{\\\"final\\\":true}\"}}";check(nativeResult("codex",codex).output().path("final").asBoolean(),"Last Codex assistant message");
        String open="{\"type\":\"step_start\"}\n{\"type\":\"text\",\"part\":{\"type\":\"text\",\"text\":\"plain answer\"}}";check(nativeResult("opencode",open).output().path("text").asText().equals("plain answer"),"OpenCode assistant text");
        check(!nativeResult("codex","{\"type\":\"turn.completed\"}").success(),"Missing assistant message rejected");check(!nativeResult("opencode","{\"type\":\"step_finish\"}").success(),"Missing OpenCode text rejected");check(!nativeResult("codex",codex+"\nmalformed").success(),"Malformed trailing JSONL rejected");
        check(nativeResult("claude","{\"result\":\"```json\\n{\\\"ok\\\":true}\\n```\"}").output().path("ok").asBoolean(),"Claude fenced JSON");check(nativeResult("claude","{\"content\":[{\"type\":\"text\",\"text\":\"done\"}]}").output().path("text").asText().equals("done"),"Claude content envelope");check(!nativeResult("generic-cli","9007199254740992").success(),"Unsafe native JSON integer rejected");
    }
    static void configChecks(Path repo)throws Exception {
        Map<String,String> env=new HashMap<>(Map.of("EXECUTOR_HOST_ALLOWED_ROOT",root.toString(),"EXECUTOR_HOST_STATE_DIR",root.resolve("state").toString(),"EXECUTOR_HOST_BEARER_TOKEN","token","EXECUTOR_HOST_CALLBACK_KEYS","{\"key\":\"secret\"}","EXECUTOR_HOST_LAUNCHER",launcher.toString()));HostConfig config=HostConfig.parse(env);check(config.agents().isEmpty(),"Dynamic mode");
        ObjectNode value=Json.object("command",Path.of(System.getProperty("java.home"),"bin","java").toString(),"args",Json.array("literal;$(echo x)"),"cwd",root.toString(),"env",Json.object("CHILD","SOURCE"),"secrets",Json.object("PRIVATE","SECRET"),"wallTimeMs",1000,"maxStdoutBytes",1024,"maxStderrBytes",1024,"port",4100,"bearerTokenEnv","EXECUTOR_HOST_BEARER_TOKEN");env.put("SOURCE","allowed");env.put("SECRET","value");env.put("EXECUTOR_HOST_AGENTS",Json.stringify(Json.object("fixture",value)));config=HostConfig.parse(env);check(config.resolvedEnvironment(config.agents().get(0)).equals(Map.of("CHILD","allowed","PRIVATE","value")),"Environment refs resolved only at host");
        HostConfig.Profile profile=config.agents().get(0);check(HostConfig.bindingError(profile,Json.object("invocationId","run","connection",Json.object("connectionId","foreign")))!=null,"Unbound connection rejected");check(HostConfig.bindingError(profile,Json.object("invocationId","run","requestedModelId","model"))!=null,"Unsupported model refused");
        ObjectNode member=Json.object("schemaVersion",1,"workspaceExecutionId","lease","path",root.toString(),"mode","shared","sourceWorkspaceId","workspace","baseHeadSha",null,"baseBranch",null),invocation=Json.object("metadata",Json.object("tenvyr",Json.object("executionWorkspace",member)));check(HostConfig.executionCwd(profile,invocation,root,List.of()).equals(root),"Reserved workspace cwd");member.put("path","relative");rejects(()->HostConfig.executionCwd(profile,invocation,root,List.of()));member.put("path",root.toString());member.put("unknown","escape");rejects(()->HostConfig.workspace(invocation));member.remove("unknown");
        Path outside=Files.createTempDirectory("tenvyr-executor-outside-");try{Path symlink=root.resolve("escape");Files.createSymbolicLink(symlink,outside);member.put("path",symlink.toString());rejects(()->HostConfig.executionCwd(profile,invocation,root,List.of()));check(HostConfig.executionCwd(profile,invocation,root,List.of(outside)).equals(outside.toRealPath()),"Only independently authorized root can permit shared cwd");Files.delete(symlink);}finally{Files.delete(outside);}
        ObjectNode snapshot=Json.object("runtimeKind","codex","cli",Json.object("command",value.get("command"),"args",Json.array(),"cwd",root.toString(),"modelArgvPrefix",Json.array("--model")),"declaredCapabilities",Json.object("structuredResult",Json.object("supported",true)));HostConfig.Profile frozen=config.revisionProfile("runtime",snapshot,"connection",Json.hash(snapshot));check(Supervisor.composeArgv(frozen,"vendor/model").equals(List.of("--model","vendor/model")),"Fixed model argv separation");
        ObjectNode modelInvocation=Json.object("connection",Json.object("connectionId","connection","configHash",Json.hash(snapshot)),"requestedModelId","bad;command");check(HostConfig.bindingError(frozen,modelInvocation)!=null,"Model injection rejected");modelInvocation.put("requestedModelId","vendor/model");check(HostConfig.bindingError(frozen,modelInvocation)==null,"Bound model accepted");
        for(JsonNode invalid:List.of(Json.value(0),Json.value(1.5),Json.value(86400001))){ObjectNode bad=value.deepCopy();bad.set("wallTimeMs",invalid);rejects(()->HostConfig.parseProfile("fixture",bad,env,root));}ObjectNode badCommand=value.deepCopy();badCommand.put("command","relative");rejects(()->HostConfig.parseProfile("fixture",badCommand,env,root));ObjectNode badBinding=value.deepCopy();badBinding.put("connectionId","unpaired");rejects(()->HostConfig.parseProfile("fixture",badBinding,env,root));
    }
    static void realTreeKill(String mode,boolean timeout)throws Exception {Path pidFile=root.resolve(mode+"-pid");AtomicLong leader=new AtomicLong();Supervisor.Outcome outcome=Supervisor.supervise(launcher,profile(mode,700,65536,65536,"generic-cli",pidFile.toString()),Map.of(),Json.object(),null,new Cancellation(),null,root,leader::set,100);check(Files.exists(pidFile),"Grandchild started for "+mode);long child=Long.parseLong(Files.readString(pidFile));for(int i=0;i<200&&ProcessHandle.of(child).map(ProcessHandle::isAlive).orElse(false);i++)Thread.sleep(10);check(!ProcessHandle.of(child).map(ProcessHandle::isAlive).orElse(false),"Grandchild process group killed for "+mode);check(!ProcessHandle.of(leader.get()).map(ProcessHandle::isAlive).orElse(false),"Session leader reaped");check(timeout?outcome.kind().equals("killed")&&outcome.finalSignal().equals("SIGKILL"):outcome.kind().equals("succeeded"),"Escalation and normal-exit orphan outcomes");}
    static void orphanChecks()throws Exception {Path state=root.resolve("orphan-state");Process orphan=new ProcessBuilder(launcher.toString(),"exec",Path.of(System.getProperty("java.home"),"bin","java").toString(),"-cp",System.getProperty("java.class.path"),FakeProcess.class.getName(),"sleep").start();try{Thread.sleep(100);String start=orphan.toHandle().info().startInstant().orElseThrow().toString();RunState.write(state,"fixture",new RunState.State("old-run",orphan.pid(),start,Instant.now().plusSeconds(10).toString()));check(RunState.read(state,"fixture").pid()==orphan.pid(),"Atomic orphan state");check(RunState.terminate(state,"fixture",launcher,100).equals("old-run"),"Verified orphan terminated");check(orphan.waitFor(2,TimeUnit.SECONDS),"Orphan reaped");}finally{Supervisor.killGroup(launcher,orphan.pid(),"KILL");orphan.destroyForcibly();}
        Process innocent=new ProcessBuilder(launcher.toString(),"exec",Path.of(System.getProperty("java.home"),"bin","java").toString(),"-cp",System.getProperty("java.class.path"),FakeProcess.class.getName(),"sleep").start();try{Thread.sleep(100);RunState.write(state,"fixture",new RunState.State("stale",innocent.pid(),"2000-01-01T00:00:00Z",Instant.now().toString()));check(RunState.terminate(state,"fixture",launcher,0)==null&&innocent.isAlive(),"PID reuse guard refuses stale identity");}finally{Supervisor.killGroup(launcher,innocent.pid(),"KILL");innocent.waitFor();}}
}
